def main():
    if sys.version_info < (3, 11):
        raise SystemExit('Python 3.11 or newer is required')
    files = json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
    with tempfile.TemporaryDirectory(prefix='the-ledger-probe-') as temp:
        root = Path(temp)
        for name, content in files.items():
            relative = Path(name)
            if relative.is_absolute() or '..' in relative.parts:
                raise SystemExit('Invalid bundled path')
            target = root/relative
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(base64.b64decode(content))
        zoneinfo.reset_tzpath([str(root/'tzdata'), *zoneinfo.TZPATH])
        sys.path.insert(0, str(root))
        from collector.probe import main as run
        return run()

if __name__ == '__main__':
    raise SystemExit(main())
